from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Label 4-connected zero regions; those not touching the edge are holes.
    zero_region = [[-1] * w for _ in range(h)]
    regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or zero_region[r][c] != -1:
                continue
            idx = len(regions)
            q = deque([(r, c)])
            zero_region[r][c] = idx
            cells = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0
                            and zero_region[ny][nx] == -1):
                        zero_region[ny][nx] = idx
                        q.append((ny, nx))
            regions.append((cells, touches_edge))

    # Find 1-components that border at least one enclosed zero region.
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            comp = []
            borders_hole = False
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if not (0 <= ny < h and 0 <= nx < w):
                        continue
                    if grid[ny][nx] == 1 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((ny, nx))
                    elif grid[ny][nx] == 0:
                        rid = zero_region[ny][nx]
                        if rid >= 0 and not regions[rid][1]:
                            borders_hole = True

            if not borders_hole:
                continue

            for y, x in comp:
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0:
                        rid = zero_region[ny][nx]
                        if rid >= 0 and not regions[rid][1]:
                            out[ny][nx] = 3
                        else:
                            out[ny][nx] = 2

    return out

