def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            colors = {}
            for y, x in cells:
                colors.setdefault(grid[y][x], []).append((y, x))

            def box_area(points):
                ys = [p[0] for p in points]
                xs = [p[1] for p in points]
                return (max(ys) - min(ys) + 1) * (max(xs) - min(xs) + 1)

            layers = sorted(colors, key=lambda color: box_area(colors[color]), reverse=True)
            replacement = dict(zip(layers, reversed(layers)))
            for y, x in cells:
                out[y][x] = replacement[grid[y][x]]

    return out

def transform(grid):
